/**
 * Built-in connector of the always-installed `ihub` installation
 * (`com.intrafind/ihub`): the iHub tools users call in chats — `ask_user`
 * and the scheduled-task tools — under the ids they always had, so
 * prompts and the loop's own rules (`isInteractiveTool`, the scheduling gate)
 * keep working. An app binds the installation (`integrations.ihub`).
 *
 * Tools generated by another iHub feature stay with that feature (Unified
 * Integrations concept §6.9): the project knowledge tools with projects
 * (`services/knowledge/knowledgeTools.js`), the agent workspace and evidence
 * tools with workflows and agents (`services/tools/platformTools.js`).
 *
 * The tool definitions are the shipped `server/defaults/tools/<id>.json`
 * files, read as data (`services/tools/shippedToolDefinitions.js`): each
 * action's parameters, model-facing description and flags come from there,
 * and `run` delegates to the implementation in `server/tools/<script>.js`
 * exactly as the tool loader does for a tool file (defaults from the schema
 * applied, `method` picked for function-style tools).
 */
import { getLocalizedString } from '../../../../../../utils/localize.js';
import {
  readShippedToolDefinitions,
  runShippedTool,
  shippedToolImplementation
} from '../../../../../tools/shippedToolDefinitions.js';

/** The file-level tool ids the installation owns (one tool per file). */
export const IHUB_TOOL_FILE_IDS = Object.freeze([
  'ask_user',
  'delete_scheduled_task',
  'get_task_run',
  'list_scheduled_tasks',
  'list_task_runs',
  'run_scheduled_task_now',
  'schedule_task',
  'update_scheduled_task'
]);

/** Flags of a tool file that other code reads from the loaded tool. */
const CARRIED_FLAGS = ['requiresUserInput', 'isAgentTool', 'passthrough', 'requiresApproval'];

const TOOLS = readShippedToolDefinitions(IHUB_TOOL_FILE_IDS);

/** The ids of iHub's own tools, as the definition's actions name them. */
export const IHUB_TOOL_IDS = Object.freeze([...TOOLS.keys()]);

function localizedText(value, language) {
  if (typeof value === 'string') return value;
  return getLocalizedString(value, language || 'en', 'en', '') || '';
}

function action(tool) {
  const extras = { enabled: true };
  for (const flag of CARRIED_FLAGS) {
    if (tool[flag] !== undefined) extras[flag] = tool[flag];
  }
  return {
    parameters: tool.parameters || { type: 'object', properties: {}, required: [] },
    description: ctx => localizedText(tool.description, ctx.language),
    extras: () => extras,
    // `params` is everything the tool call received: the model's arguments
    // plus iHub's context (`user`, `chatId`, `appConfig`, …), which the
    // implementations read themselves.
    run: (_args, ctx) => runShippedTool(tool, ctx.params || {})
  };
}

/**
 * The installation test: every tool's implementation module loads and exports
 * its function. The modules load in parallel; the steps keep the tools' order.
 * @returns {Promise<Array<{id: string, label: string, status: 'ok'|'fail', message: string}>>}
 */
async function test() {
  return Promise.all(
    [...TOOLS.values()].map(async tool => {
      try {
        await shippedToolImplementation(tool);
        return { id: tool.id, label: tool.id, status: 'ok', message: tool.script };
      } catch (error) {
        return { id: tool.id, label: tool.id, status: 'fail', message: error.message };
      }
    })
  );
}

const connector = {
  id: 'ihub',
  actions: Object.fromEntries([...TOOLS].map(([id, tool]) => [id, action(tool)])),
  test,
  status() {
    return { connected: true, toolCount: TOOLS.size };
  },
  invalidate() {},
  onChanged() {}
};

export default connector;
